"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[8287],{8287:n=>{n.exports=JSON.parse('{"id":"base-03","slug":"base-03","trackId":"base","order":4,"title":"Как хранить криптовалюту","subtitle":"Понятные правила защиты капитала","estimatedMinutes":7,"access":"free","quizCount":3,"blueprintCount":0,"trainerIds":["HUB-CALC-04"],"markdown":"Урок 3 \xb7 4 мин \\n\\n## Кошельки \\n\\nКак правильно хранить криптовалюту \\n\\nПосле предыдущей статьи возникает логичный вопрос: \\n\\nгде вообще хранится криптовалюта и как сделать так, чтобы её никто не украл? \\n\\nПервое, что важно понять: криптовалюта не лежит внутри телефона, компьютера или даже маленького устройства, известного как холодный кошелек. Она существует в блокчейне. Кошелёк хранит то, что позволяет управлять этой криптовалютой — приватные ключи . Можно представить блокчейн как огромный сейф с множеством ячеек. \\n\\nТвои средства находятся в одной из таких ячеек, а приватный ключ — это ключ, который позволяет ими распоряжаться. Именно поэтому безопасность кошелька в первую очередь означает безопасность твоих ключей. \\n\\n### Горячие и холодные кошельки \\n\\nКриптовалютные кошельки обычно разделяют на две большие категории: \\n- горячие; \\n- холодные. \\n\\n#### Горячий кошелёк \\n\\nГорячий кошелёк работает на устройстве, подключённом к интернету. Например: \\n- приложение на телефоне; \\n- приложение на компьютере; \\n- расширение в браузере. \\n\\nГлавное преимущество — удобство. Открыл приложение, подтвердил операцию — готово. Но вместе с удобством появляется дополнительный риск: ключи находятся на устройстве, которое регулярно взаимодействует с интернетом и другими программами. Особенно осторожно стоит относиться к кошелькам на основном рабочем компьютере . \\n\\nТы скачиваешь файлы, открываешь документы, устанавливаешь программы, пользуешься браузером, Telegram и почтой. Достаточно однажды запустить вредоносный файл — и на компьютере может появиться infostealer , программа, предназначенная для кражи паролей, cookies, данных приложений и другой чувствительной информации. Поэтому хранить значительные суммы на компьютере, которым ты пользуешься каждый день, — не лучшая идея. \\n\\nНо это не означает, что горячий кошелёк автоматически небезопасен. Отдельный смартфон или другое устройство, которое используется исключительно для криптовалюты и на которое не устанавливаются другие программы, защищает вас от подавляющего количества атак. \\n\\nНажми, чтобы приблизить \\n\\n### А холодный кошелёк безопасен? \\n\\nОбычно новичку говорят: \\n\\n> \\n\\nКупи аппаратный кошелёк — и всё будет безопасно. \\n\\nНа практике всё сложнее. Холодный кошелёк хранит ключи на отдельном устройстве и старается не отдавать их компьютеру или телефону. Это действительно защищает от многих распространённых атак. Например, вирус на компьютере не должен просто взять и прочитать приватный ключ из аппаратного кошелька. \\n\\nНо холодный кошелёк — не грааль и не абсолютная защита . В программном обеспечении и прошивках таких устройств периодически обнаруживаются уязвимости. Некоторые ошибки могут влиять на безопасность генерации секретных ключей, другие - на правильность отображения и подтверждения транзакций. \\n\\nКроме того, существуют риски поддельных или заранее скомпрометированных устройств, а также вредоносного программного обеспечения, через которое пользователь взаимодействует с кошельком. За последние 2 года кратно участились случаи кражи средств с заранее скомпрометированных устройств. Ущерб оценивается в сотни миллионов долларов. \\n\\nПоэтому важно понимать: холодный кошелёк - это не гарантия того, что твои средства невозможно украсть. Главная мысль другая: \\n\\nне существует устройства, покупка которого автоматически делает твои деньги неуязвимыми. \\n\\nБезопасность — это всегда система из нескольких уровней защиты. \\n\\n### Горячий кошелёк может быть достаточно безопасным \\n\\nДля обычного пользователя хорошо защищённый горячий кошелёк на отдельном устройстве будет вполне разумным вариантом. Особенно если добавить второй уровень защиты — мультиподпись . И вот здесь становится действительно интересно. \\n\\n### Что такое мультиподпись \\n\\nОбычный криптовалютный кошелёк работает примерно так: \\n\\n1 ключ → можно отправить деньги \\n\\nУкрали этот ключ — получили контроль над средствами. Мультиподпись, или multisig , позволяет потребовать несколько независимых подтверждений. Например: \\n\\nУстройство №1 + устройство №2 → транзакция разрешена \\n\\nЭто называется схемой 2/2 : \\n\\nесть два ключа, и для отправки денег нужны обе подписи. Представим, что первый ключ находится на одном смартфоне, а второй — на другом отдельном устройстве. Если злоумышленник заразит первое устройство и получит доступ к одному ключу, этого недостаточно. Ему всё ещё нужна вторая подпись. \\n\\nЕсли украдут один телефон — этого тоже недостаточно. Если скомпрометируют один кошелёк — средства всё равно нельзя просто перевести. Чтобы украсть деньги, атакующему приходится скомпрометировать две независимые точки одновременно . Поэтому мультиподпись значительно увеличивает безопасность хранения. \\n\\n### У схемы 2/2 есть недостаток \\n\\nЕсли для операции нужны две подписи из двух: \\n\\n2/2 \\n\\nи ты потерял доступ к одному из ключей, подписать транзакцию больше нельзя. Безопасность от кражи становится выше, но появляется риск самому потерять доступ. Поэтому резервное восстановление каждого ключа нужно продумывать заранее. Существуют и другие схемы, например: \\n\\n2/3 \\n\\nТогда существуют три независимых ключа, но для операции достаточно любых двух. Потеря одного ключа не блокирует доступ к средствам. Какую модель использовать — зависит от суммы, удобства и того, какие риски ты хочешь минимизировать. \\n\\nКто доберётся до твоих денег? \\n\\nТапни ключ: украли → потерял → на месте Ты можешь перевести Вор не может перевести Всё на месте. Вору нужно добыть два ключа сразу — это намного сложнее. \\n\\n### Так что всё-таки выбрать? \\n\\nХолодный кошелёк хорошо изолирует ключи от обычного компьютера и защищает от многих типов вредоносных программ. Но появляется риск поставщика, у которого вы купили устройство и уязвимость прошивки. Эти риски сложно контролировать. Горячий кошелёк значительно удобнее и при грамотной настройке тоже может быть достаточно безопасным. \\n\\nМультиподпись позволяет пойти ещё дальше и сделать так, чтобы компрометации одного устройства было недостаточно для кражи средств. Поэтому правильнее спрашивать не: \\n\\n\xabКакой кошелёк самый безопасный?\xbb \\n\\nа: \\n\\n\xabЧто должен сделать злоумышленник, чтобы получить мои деньги?\xbb \\n\\nЕсли ответ: \\n\\n> \\n\\nукрасть один пароль или получить доступ к одному компьютеру, \\n\\nзащита слабая. Если ему нужно независимо скомпрометировать несколько устройств и несколько ключей — задача становится намного сложнее. Именно к такой системе хранения и стоит стремиться. Дальше разберём всё на практике: \\n\\nГайд 1 — создание и настройка кошелька OKX \\n\\nГайд 2 — создание мультиподписи 2/2 с подтверждением операции с двух независимых устройств \\n\\n### Проверь себя 1 / 3 \\n\\nГде на самом деле находится криптовалюта? \\n\\n\\n### Встроенные термины урока:\\n- **Блокчейн** — таблица всех транзакций, которую видят все: добавить запись можно, изменить старую нельзя. Хранится одновременно на миллионах компьютеров, поэтому подделать историю физически невозможно\\n- **Холодный кошелёк** — личное хранилище крипты, где приватный ключ только у тебя. Крупные суммы хранят именно так, а не на бирже\\n- **Приватный ключ** — то, что позволяет распоряжаться криптовалютой на адресе. Сама крипта лежит в блокчейне, а кошелёк хранит ключи — поэтому защищать нужно именно их\\n- **Горячий кошелёк** — кошелёк в приложении на устройстве с интернетом: телефон, компьютер, расширение браузера. Удобно, но ключи рядом со всем, что ты скачиваешь; на отдельном устройстве — заметно безопаснее\\n- **Мультиподпись (multisig)** — кошелёк, где для перевода нужны подписи с нескольких устройств, например 2 из 2 или 2 из 3. Украли один ключ — денег всё равно не вывести\\n\\n### Проверочный тест после урока (\xabПроверь себя\xbb):\\n**Вопрос 1: Где на самом деле находится криптовалюта?**\\n- ⚪ Вариант 1: Внутри приложения кошелька\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: В блокчейне, а кошелёк хранит доступ к управлению ею\\n- ⚪ Вариант 3: Внутри телефона или Ledger\\n\\n**Вопрос 2: Почему холодный кошелёк не является абсолютной гарантией безопасности?**\\n- ⚪ Вариант 1: Потому что аппаратные кошельки вообще не защищают ключи\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: Потому что остаются риски ошибок пользователя, прошивки, вредоносного ПО и самого устройства\\n- ⚪ Вариант 3: Потому что холодный кошелёк нельзя использовать без банка\\n\\n**Вопрос 3: В чём главное преимущество мультиподписи 2/2?**\\n- ⚪ Вариант 1: Для перевода достаточно украсть любой один ключ\\n- ✅ **[ВЕРНЫЙ ОТВЕТ]** Вариант 2: Для операции требуются два независимых подтверждения\\n- ⚪ Вариант 3: Она полностью исключает возможность потерять доступ к деньгам\\n\\n\\n---","blueprints":[],"quiz":[{"id":"q-base-03-1","prompt":"Где на самом деле находится криптовалюта?","options":[{"id":"base-03-1-1","label":"Внутри приложения кошелька","isCorrect":false,"feedback":"Неверно. В блокчейне, а кошелёк хранит доступ к управлению ею"},{"id":"base-03-1-2","label":"В блокчейне, а кошелёк хранит доступ к управлению ею","isCorrect":true,"feedback":"Верно. В блокчейне, а кошелёк хранит доступ к управлению ею"},{"id":"base-03-1-3","label":"Внутри телефона или Ledger","isCorrect":false,"feedback":"Неверно. В блокчейне, а кошелёк хранит доступ к управлению ею"}],"explanation":"В блокчейне, а кошелёк хранит доступ к управлению ею","sourceRef":"CAPITAL_BASE:603–606 (Verbatim)"},{"id":"q-base-03-2","prompt":"Почему холодный кошелёк не является абсолютной гарантией безопасности?","options":[{"id":"base-03-2-1","label":"Потому что аппаратные кошельки вообще не защищают ключи","isCorrect":false,"feedback":"Неверно. Потому что остаются риски ошибок пользователя, прошивки, вредоносного ПО и самого устройства"},{"id":"base-03-2-2","label":"Потому что остаются риски ошибок пользователя, прошивки, вредоносного ПО и самого устройства","isCorrect":true,"feedback":"Верно. Потому что остаются риски ошибок пользователя, прошивки, вредоносного ПО и самого устройства"},{"id":"base-03-2-3","label":"Потому что холодный кошелёк нельзя использовать без банка","isCorrect":false,"feedback":"Неверно. Потому что остаются риски ошибок пользователя, прошивки, вредоносного ПО и самого устройства"}],"explanation":"Потому что остаются риски ошибок пользователя, прошивки, вредоносного ПО и самого устройства","sourceRef":"CAPITAL_BASE:608–611 (Verbatim)"},{"id":"q-base-03-3","prompt":"В чём главное преимущество мультиподписи 2/2?","options":[{"id":"base-03-3-1","label":"Для перевода достаточно украсть любой один ключ","isCorrect":false,"feedback":"Неверно. Для операции требуются два независимых подтверждения"},{"id":"base-03-3-2","label":"Для операции требуются два независимых подтверждения","isCorrect":true,"feedback":"Верно. Для операции требуются два независимых подтверждения"},{"id":"base-03-3-3","label":"Она полностью исключает возможность потерять доступ к деньгам","isCorrect":false,"feedback":"Неверно. Для операции требуются два независимых подтверждения"}],"explanation":"Для операции требуются два независимых подтверждения","sourceRef":"CAPITAL_BASE:613–616 (Verbatim)"}],"source":{"file":"00_FREE_GIFT_MakeCash_Crypto_And_Capital_Base_15_Lessons.md","sha256":"88a3efb162434bb8a9b3b000caee579d9c27005a8ea46ddf4ef9cafb50dc45cc","lineStart":469,"lineEnd":621}}')}}]);